'use strict';

/**
 * Rafeequl Hifz — Mutashabihat (similar-verse) suggestions.
 *
 * Loads web/data/mutashabihat.json lazily (generated by
 * config/build_mutashabihat.php) and exposes a small API used by the mistake
 * modal:
 *
 *   await Mutashabihat.suggest(surah, ayah, limit) -> [{ surah, ayah, label, text }]
 *   await Mutashabihat.text(surah, ayah)           -> ayah text (offline bundle)
 *   Mutashabihat.label(surah, ayah)                -> "سورة البقرة · الآية 35"
 *
 * Everything is local; the service worker caches both JSON files, so the
 * modal works offline after the first visit.
 */

(function () {
  let data = null;
  let dataPromise = null;
  let quran = null;
  let quranPromise = null;

  function surahName(n) {
    if (window.I18N) return I18N.getSurahName(n);
    const list = window.SURAHS_DATA || [];
    const s = list.find((x) => Number(x.id) === Number(n));
    return s ? (s.name_ar || s.name_en || s.name || String(n)) : String(n);
  }

  function label(surah, ayah) {
    const prefix = (window.I18N && I18N.lang === 'en') ? 'Surah ' : 'سورة ';
    const ayahText = window.I18N
      ? I18N.t('ayah_label', { num: ayah })
      : ('الآية ' + ayah);
    return prefix + surahName(surah) + ' · ' + ayahText;
  }

  function load() {
    if (data) return Promise.resolve(data);
    if (dataPromise) return dataPromise;
    dataPromise = fetch('data/mutashabihat.json', { credentials: 'same-origin' })
      .then((r) => (r.ok ? r.json() : null))
      .then((json) => {
        data = (json && json.verses && typeof json.verses === 'object') ? json : { verses: {} };
        return data;
      })
      .catch(() => {
        data = { verses: {} };
        return data;
      });
    return dataPromise;
  }

  function loadQuran() {
    if (quran) return Promise.resolve(quran);
    // Reuse the page-notes cache when that module already loaded the bundle.
    if (window.PageNotes && PageNotes.quran) {
      quran = PageNotes.quran;
      return Promise.resolve(quran);
    }
    // If page-notes is already fetching the bundle, wait for that request
    // instead of downloading the 1.3 MB file a second time.
    if (window.PageNotes && PageNotes.quranLoading) {
      quranPromise = PageNotes.quranLoading
        .then((json) => {
          quran = PageNotes.quran || json || {};
          return quran;
        })
        .catch(() => {
          quran = {};
          return quran;
        });
      return quranPromise;
    }
    if (quranPromise) return quranPromise;
    quranPromise = fetch('data/quran-uthmani.json', { credentials: 'same-origin' })
      .then((r) => (r.ok ? r.json() : null))
      .then((json) => {
        quran = json || {};
        return quran;
      })
      .catch(() => {
        quran = {};
        quranPromise = null;
        return quran;
      });
    return quranPromise;
  }

  async function text(surah, ayah) {
    const q = await loadQuran();
    const list = q[String(surah)];
    if (!list) return '';
    return list[ayah - 1] || '';
  }

  /**
   * @returns {Promise<Array<{surah:number, ayah:number, label:string}>>}
   */
  async function suggest(surah, ayah, limit = 6) {
    const s = parseInt(surah, 10);
    const a = parseInt(ayah, 10);
    if (!s || !a) return [];
    const d = await load();
    const raw = d.verses[s + ':' + a];
    if (!Array.isArray(raw)) return [];
    return raw.slice(0, limit).map((pair) => {
      const ts = parseInt(pair[0], 10);
      const ta = parseInt(pair[1], 10);
      return { surah: ts, ayah: ta, label: label(ts, ta) };
    }).filter((r) => r.surah > 0 && r.ayah > 0);
  }

  window.Mutashabihat = { load, suggest, text, label, surahName };
})();
